Here is the commit message:
fbdev: of: display_timing: fix refcount leak in
 of_get_display_timings()

of_parse_phandle() returns a device_node with refcount incremented,
which is stored in 'entry' and then copied to 'native_mode'. When the
error paths at lines 184 or 192 jump to 'entryfail', native_mode's
refcount is not decremented, causing a refcount leak.

Fix this by changing the goto target from 'entryfail' to 'timingfail',
which properly calls of_node_put(native_mode) before cleanup.

Fixes: cc3f414cf2e4 ("video: add of helper for display timings/videomode")
Cc: stable@vger.kernel.org
Signed-off-by: Weigang He <geoffreyhe2@gmail.com>
Signed-off-by: Helge Deller <deller@gmx.de>

Here is the root cause:
In function `of_get_display_timings()`, the device node `native_mode` obtained via `of_parse_phandle()` has an incremented reference count. In two error paths (when `disp->num_timings == 0` and when allocation of `disp->timings` fails), the code jumps to the label `entryfail`, which does not call `of_node_put(native_mode)`, resulting in a reference leak. The fix redirects these jumps to `timingfail`, which properly decrements the reference.

Here is the patch:
  **/
 struct display_timings *of_get_display_timings(const struct device_node *np)
 {
 	struct device_node *timings_np;
 	struct device_node *entry;
 	struct device_node *native_mode;
 	struct display_timings *disp;

 	if (!np)
 		return NULL;

 	timings_np = of_get_child_by_name(np, "display-timings");
 	if (!timings_np) {
 		pr_err("%pOF: could not find display-timings node\n", np);
 		return NULL;
 	}

 	disp = kzalloc(sizeof(*disp), GFP_KERNEL);
 	if (!disp) {
 		pr_err("%pOF: could not allocate struct disp'\n", np);
 		goto dispfail;
 	}

 	entry = of_parse_phandle(timings_np, "native-mode", 0);
 	/* assume first child as native mode if none provided */
 	if (!entry)
 		entry = of_get_next_child(timings_np, NULL);
 	/* if there is no child, it is useless to go on */
 	if (!entry) {
 		pr_err("%pOF: no timing specifications given\n", np);
 		goto entryfail;
 	}

 	pr_debug("%pOF: using %pOFn as default timing\n", np, entry);

 	native_mode = entry;

 	disp->num_timings = of_get_child_count(timings_np);
 	if (disp->num_timings == 0) {
 		/* should never happen, as entry was already found above */
 		pr_err("%pOF: no timings specified\n", np);
-		goto entryfail;
+		goto timingfail;
 	}

 	disp->timings = kcalloc(disp->num_timings,
 				sizeof(struct display_timing *),
 				GFP_KERNEL);
 	if (!disp->timings) {
 		pr_err("%pOF: could not allocate timings array\n", np);
-		goto entryfail;
+		goto timingfail;
 	}

 	disp->num_timings = 0;
 	disp->native_mode = 0;

 	for_each_child_of_node(timings_np, entry) {
 		struct display_timing *dt;
 		int r;

 		dt = kmalloc(sizeof(*dt), GFP_KERNEL);
 		if (!dt) {
 			pr_err("%pOF: could not allocate display_timing struct\n",
 				np);
 			goto timingfail;
 		}

 		r = of_parse_display_timing(entry, dt);
 		if (r) {
 			/*
 			 * to not encourage wrong devicetrees, fail in case of
 			 * an error
 			 */
 			pr_err("%pOF: error in timing %d\n",
 				np, disp->num_timings + 1);
 			kfree(dt);
 			goto timingfail;
 		}

 		if (native_mode == entry)
 			disp->native_mode = disp->num_timings;

 		disp->timings[disp->num_timings] = dt;
 		disp->num_timings++;
 	}
 	of_node_put(timings_np);
 	/*
 	 * native_mode points to the device_node returned by of_parse_phandle
 	 * therefore call of_node_put on it
 	 */
 	of_node_put(native_mode);

 	pr_debug("%pOF: got %d timings. Using timing #%d as default\n",
 		np, disp->num_timings,
 		disp->native_mode + 1);

 	return disp;

 timingfail:
 	of_node_put(native_mode);
 	display_timings_release(disp);
 	disp = NULL;
 entryfail:
 	kfree(disp);
 dispfail:
 	of_node_put(timings_np);
 	return NULL;
 }
 EXPORT_SYMBOL_GPL(of_get_display_timings);


